$file = "g:\0.CMS-MAIN-ALL\chke or\StudentChecking_ChiTiet.repx"
$content = [System.IO.File]::ReadAllText($file)
for ($i = 31; $i -ge 1; $i--) {
    $old = "pCol$i"
    $temp = "TEMP_COL$($i - 1)"
    $content = $content.Replace($old, $temp)
}
for ($i = 0; $i -le 30; $i++) {
    $temp = "TEMP_COL$i"
    $new = "pCol$i"
    $content = $content.Replace($temp, $new)
}
[System.IO.File]::WriteAllText($file, $content)
Write-Host "Done. Sample counts:"
@("pCol0","pCol1","pCol30","pCol31") | ForEach-Object { Write-Host "$_ : $((Select-String -InputObject $content -Pattern $_ -AllMatches).Matches.Count)" }

$file = "g:\0.CMS-MAIN-ALL\chke or\StudentChecking_ChiTiet.repx"
$content = Get-Content $file -Raw
0..30 | ForEach-Object {
  $n = "pCol$_"
  $decl = ([regex]::Matches($content, "Parameter $n;")).Count
  $name = ([regex]::Matches($content, '\.Name = "' + $n + '"')).Count
  if ($decl -ne 1 -or $name -ne 1) { Write-Host "MISSING or DUPLICATE: $n decl=$decl name=$name" }
}
Write-Host "Check complete"

$file = "g:\0.CMS-MAIN-ALL\chke or\StudentChecking_ChiTiet.repx"
$content = [System.IO.File]::ReadAllText($file)
for ($i = 30; $i -ge 1; $i--) {
    $old = "Value_$i"
    $temp = "TEMP_VAL$($i - 1)"
    $content = $content.Replace($old, $temp)
}
for ($i = 0; $i -le 29; $i++) {
    $temp = "TEMP_VAL$i"
    $new = "Value_$i"
    $content = $content.Replace($temp, $new)
}
[System.IO.File]::WriteAllText($file, $content)
Write-Host "Verification:"
0..30 | ForEach-Object {
  $n = "Value_$_"
  $c = ([regex]::Matches($content, [regex]::Escape('"' + $n + '"'))).Count
  if ($c -gt 0) { Write-Host "$n : $c" }
}
Write-Host "Value_31 count:" ([regex]::Matches($content, '"Value_31"')).Count
